use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

/// The hosts this node's `HTTPClient` handle is scoped to. The host enforces
/// the allowlist at the crossing (by trapping); this copy exists only so that
/// one out-of-scope subscription is recorded as a failure instead of taking
/// the whole tick down with it. The node never reaches for a host it was not
/// granted.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host of an http(s) URL, or say why it has none.
fn host_of(url: &str) -> Result<String, &'static str> {
    if url.is_empty() {
        return Err("empty url");
    }
    if url
        .chars()
        .any(|c| c == '\\' || c.is_whitespace() || c.is_control())
    {
        return Err("malformed url");
    }
    let (scheme, rest) = match url.find("://") {
        Some(i) => (&url[..i], &url[i + 3..]),
        None => return Err("url has no scheme"),
    };
    if !(scheme.eq_ignore_ascii_case("http") || scheme.eq_ignore_ascii_case("https")) {
        return Err("unsupported url scheme");
    }
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    let host = host.trim_end_matches('.');
    if host.is_empty() {
        return Err("url has no host");
    }
    Ok(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for raw in subscriptions.urls {
            let url = raw.trim();

            match host_of(url) {
                Ok(host) => {
                    if !ALLOWED_HOSTS.iter().any(|h| *h == host) {
                        failures.push(FetchFailure {
                            url: url.to_string(),
                            error: "host not in this node's allowlist; not fetched".to_string(),
                        });
                        continue;
                    }
                }
                Err(why) => {
                    failures.push(FetchFailure {
                        url: url.to_string(),
                        error: why.to_string(),
                    });
                    continue;
                }
            }

            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.to_string(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.to_string(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
